 import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { color, uv, vec2, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Box3, DirectionalLight, SpotLight, Vector3 } = THREE;

  const palette = config.intent?.visualSpec?.colors || {};
  const inkHex = palette.ink || '#16161d';
  const paperHex = palette.paper || '#e8ecf2';
  const accentHex = palette.accent || '#ff2a38';
  const surfaceHex = palette.surface || '#0b0b10';

  const node = new Group();
  node.name = config.id || 'home-thumbnail';

  const timelines = [];
  const disposables = [];

  // --- Gradient stage backdrop ---
  const backGeo = new PlaneGeometry(7, 6);
  const backMat = new MeshBasicNodeMaterial({
    colorNode: mix(color(surfaceHex), color(inkHex), uv().y),
  });
  const back = new Mesh(backGeo, backMat);
  back.position.z = -2.5;
  node.add(back);
  disposables.push(backGeo, backMat);

  // --- Local lighting ---
  const key = new DirectionalLight(new THREE.Color('#f2e8da'), 1.2);
  key.position.set(2.8, 4.0, 4.0);
  node.add(key);

  const rim = new SpotLight(new THREE.Color(accentHex), 0.9);
  rim.position.set(-3.5, 1.5, -1.5);
  rim.target.position.set(0, 0, 0);
  rim.angle = Math.PI / 4;
  rim.penumbra = 0.55;
  rim.distance = 12;
  node.add(rim);
  node.add(rim.target);

  const fill = new DirectionalLight(new THREE.Color('#8d92a0'), 0.5);
  fill.position.set(-1.0, 2.0, 5.0);
  node.add(fill);

  // --- Card body ---
  const cardW = 2.4;
  const cardH = 1.6;
  const cardD = 0.12;

  const cardGeo = new BoxGeometry(cardW, cardH, cardD);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: surfaceHex,
    metalness: 0.4,
    roughness: 0.62,
    clearcoat: 0.25,
    clearcoatRoughness: 0.35,
    anisotropy: 0.45,
    anisotropyRotation: Math.PI * 0.24,
    emissive: new THREE.Color(accentHex),
    emissiveIntensity: 0,
  });
  const card = new Mesh(cardGeo, cardMat);
  disposables.push(cardGeo, cardMat);

  // --- Caption strip ---
  const stripH = 0.32;
  const stripGeo = new BoxGeometry(cardW, stripH, cardD + 0.015);
  const stripMat = new MeshPhysicalNodeMaterial({
    color: inkHex,
    metalness: 0.12,
    roughness: 0.74,
    clearcoat: 0.12,
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardH * 0.5 + stripH * 0.5 - 0.02, 0.02);
  card.add(strip);
  disposables.push(stripGeo, stripMat);

  // --- Radial contact shadow ---
  const shadowGeo = new PlaneGeometry(1, 1, 32, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    colorNode: color('#000000').mul(
      smoothstep(0.55, 0.0, uv().sub(vec2(0.5)).length().mul(2.0))
    ).mul(0.55),
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(cardW * 1.5, cardH * 0.9, 1);
  shadow.position.set(0, -cardH * 0.55 - 0.28, -0.1);
  node.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // --- Card stage ---
  const cardStage = new Group();
  cardStage.add(card);
  cardStage.position.y = -0.15;
  cardStage.scale.setScalar(0.98);
  node.add(cardStage);

  const introTl = gsap.timeline();
  introTl.to(cardStage.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  introTl.to(cardStage.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(introTl);

  // --- GLB hero subject ---
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const subject = gltf.scene;
      if (!subject) return;

      const box = new Box3().setFromObject(subject);
      const center = new Vector3();
      const size = new Vector3();
      box.getCenter(center);
      box.getSize(size);

      const heroScale = (cardH * 0.6) / Math.max(size.x, size.y, size.z);

      subject.position.sub(center.clone().multiplyScalar(heroScale));
      subject.position.z = cardD * 0.5 + 0.1;
      subject.scale.setScalar(heroScale);

      const baseY = subject.position.y;
      subject.position.y = baseY - 0.4;
      subject.scale.setScalar(0);

      card.add(subject);

      const heroTl = gsap.timeline();
      heroTl.to(subject.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
      heroTl.to(subject.scale, {
        x: heroScale,
        y: heroScale,
        z: heroScale,
        duration: 0.8,
        ease: 'power4.out',
      }, 0.05);
      timelines.push(heroTl);
    });
  }

  // --- Interaction handlers ---
  const isHoverActive = (arg) => {
    if (arg === false || arg === null || arg === undefined) return false;
    if (arg === true) return true;
    if (typeof arg === 'object') {
      const t = String(arg.type || '');
      if (t.includes('leave') || t.includes('out') || t.includes('exit')) return false;
      if (arg.active === false || arg.active === 'false') return false;
    }
    return true;
  };

  const hover = (e) => {
    const active = isHoverActive(e);
    gsap.to(cardStage.position, {
      y: active ? 0.15 : 0,
      duration: 0.4,
      ease: 'power2.out',
      overwrite: true,
    });
    gsap.to(cardMat, {
      emissiveIntensity: active ? 0.18 : 0,
      duration: 0.35,
      ease: 'power2.out',
    });
    gsap.to(shadowMat, {
      opacity: active ? 0.35 : 0.55,
      duration: 0.35,
    });
  };

  const click = () => {
    ctx.emit('hub-home.select', { id: config.id });
    gsap.to(cardStage.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      yoyo: true,
      repeat: 1,
      ease: 'back.out(2)',
    });
  };

  node.userData.handlers = { hover, click };
  node.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => {
      try { if (d && typeof d.dispose === 'function') d.dispose(); } catch {}
    });
  };

  return node;
}
